    "fullExcerptText": "I was once a humble commoner plowing the soil in Nanyang, seeking only to preserve my life in turbulent days. The Late Sovereign condescended to visit my thatched cottage three times, consulting me on the great affairs of the realm. How can I not exhaust my devotion unto death to repay his grace? Today, our army marches north to restore the sacred capital!",
